type BaselineStep struct {
	Number     int
	Key, Label string
}

func BaselineSteps() []BaselineStep {
	return []BaselineStep{{1, "interview", "Interview"}, {2, "inventory", "Evidence"}, {3, "gap_review", "Gaps"}, {4, "plan_approval", "Plan"}, {5, "active", "Welcome"}}
}
func BaselineStepIndex(phase string) int {
	switch phase {
	case "interview":
		return 1
	case "source_access", "inventory":
		return 2
	case "gap_review":
		return 3
	case "plan_approval":
		return 4
	default:
		return 5
	}
}
func BaselineStepComplete(key, phase string) bool {
	return BaselineStepIndex(key) < BaselineStepIndex(phase)
}
func BaselineStatusLabel(value string) string {
	switch value {
	case "ready":
		return "Ready"
	case "active":
		return "In progress"
	default:
		return "Building"
	}
}
func BaselineMessageInitial(role string) string {
	if role == "user" {
		return "Y"
	}
	return "M"
}
func BaselineMessageAuthor(role string) string {
	if role == "user" {
		return "You"
	}
	return "Mia · Setup manager"
}
func BaselineSourceInitial(value string) string {
	switch value {
	case "email":
		return "E"
	case "google_drive":
		return "G"
	case "public_web":
		return "W"
	default:
		return "F"
	}
}
func SourceStatusLabel(value string) string {
	switch value {
	case "connected":
		return "Connected · read-only"
	case "error":
		return "Needs attention"
	case "disconnected":
		return "Disconnected"
	default:
		return "Available"
	}
}
func BaselineSourceDescription(value string) string {
	switch value {
	case "email":
		return "Select folders and a date range; ingest only messages and attachments that support the baseline."
	case "google_drive":
		return "Grant metadata and file-read access only to folders you explicitly select."
	case "public_web":
		return "Search the company website and authoritative registries with visible queries and citations."
	default:
		return "Upload policies, licenses, checklists, exports, contracts, and other business records."
	}
}
func BaselineDeferredSources(sources []BaselineSourceView) []BaselineSourceView {
	result := []BaselineSourceView{}
	for _, source := range sources {
		if source.Type == "email" || source.Type == "google_drive" {
			result = append(result, source)
		}
	}
	return result
}
func EvidenceInterviewPercent(answered, total int) float64 {
	if total <= 0 {
		return 0
	}
	return float64(answered) * 100 / float64(total)
}
func BaselineRecentInterviewed(requirements []EvidenceRequirementView, limit int) []EvidenceRequirementView {
	result := []EvidenceRequirementView{}
	for _, requirement := range requirements {
		if requirement.Interviewed {
			result = append(result, requirement)
		}
	}
	if limit > 0 && len(result) > limit {
		result = result[len(result)-limit:]
	}
	return result
}
func EvidenceInterviewPrompt(requirement EvidenceRequirementView) string {
	if len(requirement.Evidence) > 0 {
		return fmt.Sprintf("I found %d possible record(s) related to %s. Do these accurately document how the business works, or should we take a different next step?", len(requirement.Evidence), requirement.Label)
	}
	return fmt.Sprintf("Next, let’s cover %s. %s Do you already have this, should I help find or create it, or does it not apply?", requirement.Label, requirement.Rationale)
}
func EvidenceInterviewAcknowledgement(requirement EvidenceRequirementView) string {
	if requirement.Status == "confirmed" {
		return "Got it. I’ll treat that as verified evidence and keep its source attached to the baseline."
	}
	switch requirement.Disposition {
	case "have_it":
		return "Understood. I’ll add a follow-up to locate and verify the record without making you stop onboarding."
	case "search_sources":
		return "I’ll make this an agent research item and preserve what was searched and found."
	case "create_it":
		return "I’ll turn this into an agent work item to draft the missing business record for your review."
	case "obtain_it":
		return "I’ll track this as something the business needs to obtain, including any outside provider, authority, or cost involved."
	case "not_applicable":
		return "Understood. I’ll mark this not applicable so it does not create unnecessary work."
	default:
		return "I’ve recorded that and will carry it into the review."
	}
}
func EvidenceStatusLabel(value string) string {
	switch value {
	case "confirmed":
		return "Confirmed"
	case "partial":
		return "Partial"
	case "stale":
		return "Stale"
	case "not_applicable":
		return "Not applicable"
	case "blocked":
		return "Blocked"
	default:
		return "Missing"
	}
}
func EvidenceDispositionLabel(disposition, status string) string {
	if status == "confirmed" {
		return "Verified evidence is attached"
	}
	if status == "not_applicable" || disposition == "not_applicable" {
		return "Not applicable to this business"
	}
	switch disposition {
	case "have_it":
		return "Locate and verify the existing record"
	case "search_sources":
		return "Mia will search the available sources"
	case "create_it":
		return "Mainspring will draft the missing record"
	case "obtain_it":
		return "The business will obtain it from an outside source"
	default:
		return "Follow-up is still required"
	}
}

type ResponsibilityCount struct {
	Label string
	Count int
}

func BaselineResponsibilityCounts(requirements []EvidenceRequirementView) []ResponsibilityCount {
	counts := map[string]int{}
	for _, requirement := range requirements {
		if requirement.Status != "confirmed" && requirement.Status != "not_applicable" {
			counts[requirement.Responsibility]++
		}
	}
	return []ResponsibilityCount{{"agent tasks", counts["agent"]}, {"owner tasks", counts["owner"]}, {"shared tasks", counts["shared"]}, {"external dependencies", counts["external"]}}
}

